/// <summary>
/// Context used during MET invoice posting to cache attribute lookups for products.
/// </summary>
public class METInvoicePostingContext implements System.IDisposable
{
    private static METInvoicePostingContext currentContext;
    private Map             cache;
    private EcoResAttribute attribute;

}

Method.Source:
public static METInvoicePostingContext current()
{
    return currentContext;
}

/// <summary>
/// Initializes the context instance, creating the in-memory cache and resolving
/// the "Priced by Weight" attribute definition.
/// </summary>
/// <exception cref="Exception">Thrown if a context is already active (nested contexts are not supported).</exception>   
public void new()
{
    currentContext = this;
    cache     = new Map(Types::String, Types::Integer);
    attribute = EcoResAttribute::findByName(METConstants::PricedByWeightAttributeId,EcoResAttributeType::findByName(METConstants::EcoResAttributeTypeBoolean).RecId);
}

/// <summary>
/// Determines whether the specified product (by <paramref name="_itemId"/>) has the
/// "Priced by Weight" attribute set. Results are cached in-memory to avoid repeated
/// database lookups.
/// </summary>
/// <param name="_itemId">Product number / item identifier to check.</param>
/// <returns>True if the product is priced by weight; otherwise false.</returns>
public boolean getPricedByWeightAttributeValue(ItemId _itemId)
{
    if (cache.exists(_itemId))
    {
        return cache.lookup(_itemId) != 0;
    }

    boolean       result  = false;
    EcoResProduct product = EcoResProduct::findByProductNumber(_itemId);

    if (product && attribute)
    {
        EcoResBooleanValue          boolValue;
        EcoResProductAttributeValue prodAttrValue;

        select firstOnly BooleanValue from boolValue
          exists join prodAttrValue
              where prodAttrValue.Value     == boolValue.RecId
                 && prodAttrValue.Product   == product.RecId
                 && prodAttrValue.Attribute == attribute.RecId;

        result = boolValue.BooleanValue;
    }

    cache.insert(_itemId, result ? 1 : 0);
    return result;
}

/// <summary>
/// Disposes the context by clearing the static current instance reference.
/// After calling this method the context is no longer considered active.
/// </summary>
public void dispose()
{
    currentContext = null;
}
